import Foundation
import XCTest
import SundayKeysCore
@testable import SundayKeysApp

/// The licence gate as a run sees it: the real `AudioEngineController.noteOn` with a real
/// launch decision, and a recorder standing in for the voices.
///
/// The core suite proves what a standing decides. These cases prove what the app does with that
/// decision - that a refused note never reaches the voices, that the refusal is counted and that
/// the line the window would show is the line the gate holds - and that a note generated by the
/// arpeggiator meets the same guard as a key, because the panel plays into the controller through
/// `KeysoundNoteTarget` like everything else.
///
/// Nothing here starts an engine, opens a device or contacts a server: the controller is built
/// over a recorder, so the assertion is about what arrived at the notes' destination.
@MainActor
final class LicenceEnforcementTests: XCTestCase {
    /// 2026-01-10T00:00:00Z, the instant the stub payloads are read at.
    private let now = Date(timeIntervalSince1970: 1_768_003_200)

    private let products =
        "[{\"originProductId\":\"p1\",\"productId\":\"p1\",\"productVersion\":\"1\"}]"

    // MARK: - Fixtures

    /// Records every call that reached the voices, so "refused" means nothing was recorded rather
    /// than that a flag said so.
    private final class RecordingVoicing: KeysoundVoicing {
        private(set) var lines: [String] = []

        func noteOn(note: UInt8, velocity: UInt8) {
            lines.append("on \(note) v\(velocity)")
        }

        func noteOff(note: UInt8) {
            lines.append("off \(note)")
        }

        func allNotesOff() {
            lines.append("all off")
        }
    }

    private struct StubTransport: SessionTransport {
        let body: String

        func send(_ request: SessionRequest) async throws -> SessionResponse {
            SessionResponse(statusCode: 200, body: Data(body.utf8))
        }
    }

    /// The gate a launch would apply for this session body, through the same `SessionClient` and
    /// `SessionLaunch` the app uses - not a hand-built `LicenceGate`.
    private func gate(forSession body: String) async -> LicenceGate {
        let client = SessionClient(
            transport: StubTransport(body: body),
            endpoint: SessionEndpoint(
                url: URL(string: "https://example.invalid/api/v1/auth/session")!
            )
        )
        return LicenceGate(SessionLaunch.resolve(await client.fetch(at: now)))
    }

    private func sessionBody(licence: String) -> String {
        "{\"data\":{\"license\":\(licence),\"accessibleProducts\":\(products)}}"
    }

    // MARK: - The controller's own note path

    func testAnExpiredStandingRefusesANoteBeforeItReachesTheVoices() async {
        let voices = RecordingVoicing()
        let controller = AudioEngineController(voice: voices)
        let gate = await gate(forSession: sessionBody(licence: "{\"status\":\"expired\"}"))
        controller.setLicenceGate(gate)

        XCTAssertFalse(gate.permitsPlayback)
        XCTAssertEqual(
            controller.licenceGate.line,
            "licensed playback refused: Session refused: Licence expired: sounds downgraded"
        )

        controller.noteOn(note: 60, velocity: 100)

        XCTAssertEqual(voices.lines, [], "a refused note must not reach the voices at all")
        XCTAssertEqual(controller.refusedNotes, 1, "the refusal is counted where the app counts it")

        controller.noteOn(note: 64, velocity: 100)
        XCTAssertEqual(voices.lines, [])
        XCTAssertEqual(controller.refusedNotes, 2)
    }

    func testAnUnreadableStandingRefusesANoteBeforeItReachesTheVoices() async {
        let voices = RecordingVoicing()
        let controller = AudioEngineController(voice: voices)
        let gate = await gate(forSession: sessionBody(licence: "{\"status\":\"trialing\"}"))
        controller.setLicenceGate(gate)

        XCTAssertFalse(gate.permitsPlayback)
        XCTAssertTrue(controller.licenceGate.refusalLine?.contains("trialing") == true)

        controller.noteOn(note: 67, velocity: 90)

        XCTAssertEqual(voices.lines, [])
        XCTAssertEqual(controller.refusedNotes, 1)
    }

    /// The same call with a permitted decision still forwards, so the guard is a gate and not a
    /// mute: if this ever fails alongside the two above, the seam is not wired to the voices.
    func testAPermittedStandingStillReachesTheVoices() async {
        let voices = RecordingVoicing()
        let controller = AudioEngineController(voice: voices)
        controller.setLicenceGate(await gate(forSession: sessionBody(licence: "{\"status\":\"active\"}")))

        controller.noteOn(note: 60, velocity: 100)

        XCTAssertEqual(voices.lines, ["on 60 v100"])
        XCTAssertEqual(controller.refusedNotes, 0)
    }

    func testALaunchWithNoVerdictKeepsPlayback() {
        let voices = RecordingVoicing()
        let controller = AudioEngineController(voice: voices)

        XCTAssertEqual(controller.licenceGate, .permitted)
        controller.noteOn(note: 60, velocity: 100)
        XCTAssertEqual(voices.lines, ["on 60 v100"])
    }

    // MARK: - The arpeggiator's note path

    /// A stepped pattern plays into the controller through `KeysoundNoteTarget`, which is the same
    /// `noteOn` the keys reach. With an expired standing the pattern still runs - the panel is
    /// stepping, and it asked for notes - but none of them starts a voice, and the controller
    /// counted the refusals.
    func testAnArpeggiatorStepIsRefusedByTheSameGate() async {
        let voices = RecordingVoicing()
        let controller = AudioEngineController(voice: voices)
        controller.setLicenceGate(await gate(forSession: sessionBody(licence: "{\"status\":\"expired\"}")))

        let clock = ManualHostClock(now: 0)
        let panel = ArpeggiatorPanel(clock: clock, target: controller)
        panel.setEnabled(true)
        panel.keyDown(note: 60, velocity: 100)

        clock.now = 0.25
        panel.tick()
        clock.now = 0.5
        panel.tick()

        XCTAssertTrue(panel.isStepping, "the pattern ran, so a step was actually attempted")
        XCTAssertEqual(panel.heldNotes, [60])
        // The panel's releases still reach the voices: the guard sits on `noteOn`, and a refusal
        // that also swallowed `noteOff` could strand a voice that was already sounding when the
        // standing changed. So the case asserts that no voice is started, not that the recorder
        // is silent - the first run of this file is what showed the difference.
        XCTAssertTrue(
            voices.lines.allSatisfy { !$0.hasPrefix("on ") },
            "no refused step may start a voice, got \(voices.lines)"
        )
        XCTAssertGreaterThan(
            controller.refusedNotes,
            0,
            "the refusal came from the gate the controller enforces, not from an idle pattern"
        )
    }

    /// The control: the same commands with a licensed standing do sound, so the case above is
    /// proving the gate rather than proving that the panel is silent in a test.
    func testAnArpeggiatorStepReachesTheVoicesWhenPermitted() async {
        let voices = RecordingVoicing()
        let controller = AudioEngineController(voice: voices)
        controller.setLicenceGate(await gate(forSession: sessionBody(licence: "{\"status\":\"active\"}")))

        let clock = ManualHostClock(now: 0)
        let panel = ArpeggiatorPanel(clock: clock, target: controller)
        panel.setEnabled(true)
        panel.keyDown(note: 60, velocity: 100)

        clock.now = 0.25
        panel.tick()

        XCTAssertTrue(panel.isStepping)
        XCTAssertTrue(voices.lines.contains("on 60 v100"), "got \(voices.lines)")
        XCTAssertEqual(controller.refusedNotes, 0)
    }
}
